var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobSortResultPanel panel = null;
foreach (var r in roots) {
    panel = r.GetComponentInChildren<Sim.Jobs.JobSortResultPanel>(true);
    if (panel != null) break;
}
if (panel == null) { Debug.Log("JobSortResultPanel not found (already removed?)"); return; }
var go = panel.gameObject;
Debug.Log("Destroying: " + go.name);
UnityEngine.Object.DestroyImmediate(go, true);
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("Done. Scene saved.");
